DO $$
DECLARE
  evt RECORD;
  cur_status VARCHAR(20);
  cur_bill_date DATE;
BEGIN
  FOR evt IN SELECT * FROM renewal_events ORDER BY event_id LOOP
    SELECT renewal_status, next_bill_date INTO cur_status, cur_bill_date
    FROM subscriptions WHERE subscription_id = evt.subscription_id;

    IF evt.event_type = 1 AND cur_status = 'active' AND cur_bill_date <= evt.process_date THEN
      UPDATE subscriptions
      SET renewal_status = 'active',
          next_bill_date = evt.new_bill_date,
          renewal_count = renewal_count + 1
      WHERE subscription_id = evt.subscription_id;
    ELSIF evt.event_type = 2 AND cur_status = 'active' THEN
      UPDATE subscriptions
      SET renewal_status = 'paused',
          paused_at = evt.process_date
      WHERE subscription_id = evt.subscription_id;
    ELSIF evt.event_type = 3 AND cur_status = 'paused' THEN
      UPDATE subscriptions
      SET renewal_status = 'active',
          next_bill_date = evt.new_bill_date,
          paused_at = NULL
      WHERE subscription_id = evt.subscription_id;
    END IF;
  END LOOP;
END $$;

SELECT * FROM subscriptions ORDER BY subscription_id;
